const slug = (text) => 'terms-' + text.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');

// The numbered section headings, for a table of contents.
export const TERMS_SECTIONS = TERMS_BLOCKS.filter(([k]) => k === 'h1').map(([, text]) => ({ id: slug(text), text }));

// Renders the full document. Consecutive bullets are grouped into one list.
export function termsHTML({ includeTitle = true } = {}) {
  const out = [];
  let list = [];
  const flush = () => {
    if (list.length) out.push(`<ul class="terms-list">${list.map((t) => `<li>${esc(t)}</li>`).join('')}</ul>`);
    list = [];
  };
  for (const [kind, text] of TERMS_BLOCKS) {
    if (kind === 'li') { list.push(text); continue; }
    flush();
    if (kind === 'title') { if (includeTitle) out.push(`<h2 class="terms-title">${esc(text)}</h2>`); }
    else if (kind === 'h1') out.push(`<h3 class="terms-h1" id="${slug(text)}">${esc(text)}</h3>`);
    else if (kind === 'h2') out.push(`<h4 class="terms-h2">${esc(text)}</h4>`);
    else if (kind === 'strong') out.push(`<p class="terms-p"><strong>${esc(text)}</strong></p>`);
    else out.push(`<p class="terms-p">${esc(text)}</p>`);
  }
  flush();
  return `<div class="terms-doc">${out.join('')}</div>`;
}
